    /// Starts the session of `<invoke srcexpr>` `missing_run` (W3C SCXML 6.4): the
    /// value `srcexpr` computes names, by its document stem, one of the candidates the
    /// invoke declares (docs/SCE_ACCEPTED_SUBSET.md §2.13), which is the one started.
    private func sceStartInvokeMissingRun(_ pending: PendingInvoke<StaticInvokeHybridState>, engine: Engine<StaticInvokeHybridPolicy>) {
        // §scxml-6.4: the `srcexpr` is read now, as the invocation starts, so what the
        // entry actions of the state left is what it names. One that cannot be
        // evaluated is an attribute that cannot be: `error.execution`, and nothing starts.
        let sceSelected = documentStem(self.vPick)
        // W3C SCXML C.1: the child is known by the id its parent mints for it.
        let childSessionID = "\(sessionID).\(pending.invokeID)"
        let sceStarted: any ChildEngine
        if sceSelected.utf8.elementsEqual("static_hybrid_first".utf8) {
            // The stem names the document the build wrote a child for, and its
            // arguments are read only now that the value has chosen it (6.4.3).
            let childPolicy = StaticHybridFirstPolicy()
            var seed = StaticHybridFirstPolicy.InvokeParams()
            do {
                seed.vStart = self.vBase
            }
            do {
                seed.vEnabled = self.vEnabled
            }
            childPolicy.acceptParams(seed)

            let session = InvokedSession(
                policy: childPolicy,
                sessionID: childSessionID,
                queue: ParentEventQueue()
            )
            session.engine.setClock(engine.clock())
            sceStarted = session
        } else if sceSelected.utf8.elementsEqual("static_hybrid_second".utf8) {
            // The stem names the document the build wrote a child for, and its
            // arguments are read only now that the value has chosen it (6.4.3).
            let childPolicy = StaticHybridSecondPolicy()
            var seed = StaticHybridSecondPolicy.InvokeParams()
            do {
                seed.vStart = self.vBase
            }
            childPolicy.acceptParams(seed)

            let session = InvokedSession(
                policy: childPolicy,
                sessionID: childSessionID,
                queue: ParentEventQueue()
            )
            session.engine.setClock(engine.clock())
            sceStarted = session
        } else {
            // A value naming none of the declared candidates is the failure the
            // Interpreter reports when a document will not load: nothing is created,
            // and, as there, the arguments are not read.
            engine.raise(EventWithMetadata.platformError(StaticInvokeHybridEvent.errorExecution, message: "<invoke srcexpr> evaluated to a document it did not declare"))
            return
        }
        // W3C SCXML 6.4.1: tracked before the child initializes.
        activeInvokes["missing_run"] = ChildSession(
            sessionID: childSessionID,
            invokeID: "missing_run",
            parentSessionID: sessionID,
            autoforward: false,
            finalizeScript: ""
        )
        sceStarted.initialize()
        sceInvokeChildMissingRun = sceStarted
        sceSettleInvokeMissingRun(engine: engine)
    }

    /// Takes what the session of `<invoke>` `missing_run` sent this machine, and
