    /// Ticks the running sessions (W3C SCXML 6.4): what a child sent before is taken
    /// first, then the child takes its turn, then what it sent in it.
    public func tickChildren(engine: Engine<StaticInvokeHybridPolicy>) {
        if !sceInvokeDoneFirstRun, let child = sceInvokeChildFirstRun {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "first_run",
                engine: engine
            )
            child.tick()
            sceSettleInvokeFirstRun(engine: engine)
        }
        if !sceInvokeDoneLossyRun, let child = sceInvokeChildLossyRun {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "lossy_run",
                engine: engine
            )
            child.tick()
            sceSettleInvokeLossyRun(engine: engine)
        }
        if !sceInvokeDoneMissingRun, let child = sceInvokeChildMissingRun {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "missing_run",
                engine: engine
            )
            child.tick()
            sceSettleInvokeMissingRun(engine: engine)
        }
        if !sceInvokeDoneSecondRun, let child = sceInvokeChildSecondRun {
            drainAndRaiseChildEvents(
                childEngine: child,
                activeInvokes: activeInvokes,
                invokeKey: "second_run",
                engine: engine
            )
            child.tick()
            sceSettleInvokeSecondRun(engine: engine)
        }
    }

    /// Settles what every running child sent this machine while a delivery drove it
    /// (docs/adr/0045): one body for every drive of a child, so a save at any boundary
    /// of this session finds its buffer empty.
    public func settleChildren(engine: Engine<StaticInvokeHybridPolicy>) {
        sceSettleInvokeFirstRun(engine: engine)
        sceSettleInvokeLossyRun(engine: engine)
        sceSettleInvokeMissingRun(engine: engine)
        sceSettleInvokeSecondRun(engine: engine)
    }

    /// The nearest deadline of a running child (W3C SCXML 6.4), so a host that walks
    /// time by `timeUntilNextScheduled` does not step over a timer a child armed. A
    /// child that has ended is skipped: the policy keeps it until its state exits, and
    /// what it armed is no longer owed.
    public func nextChildDeadline() -> Duration? {
        var soonest: Duration?
        if !sceInvokeDoneFirstRun, let due = sceInvokeChildFirstRun?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneLossyRun, let due = sceInvokeChildLossyRun?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneMissingRun, let due = sceInvokeChildMissingRun?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        if !sceInvokeDoneSecondRun, let due = sceInvokeChildSecondRun?.timeUntilNextScheduled() {
            soonest = soonest.map { min($0, due) } ?? due
        }
        return soonest
    }

    /// Delivers a delayed `<send target="#_<invokeid>">` whose wait is over, by name:
    /// a child need not declare every event its parent sends (W3C SCXML 6.2 + 6.4).
    /// Whether the invocation was there to take it: one whose session has reached its
    /// final state has ended, and the engine reports the send it could not deliver
    /// (W3C SCXML C.1).
    public func deliverToInvocation(invokeID: String, eventName: String, eventData: String, sendID: String) -> Bool {
        if invokeID.utf8.elementsEqual("first_run".utf8) {
            if let child = sceInvokeChildFirstRun, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("lossy_run".utf8) {
            if let child = sceInvokeChildLossyRun, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("missing_run".utf8) {
            if let child = sceInvokeChildMissingRun, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        if invokeID.utf8.elementsEqual("second_run".utf8) {
            if let child = sceInvokeChildSecondRun, !child.isInFinalState {
                deliverToChild(child, eventName: eventName, eventData: eventData)
                return true
            }
            return false
        }
        return false
    }

    /// Whether `#_<invokeid>` names an invocation running now (W3C SCXML 6.4 + C.1):
    /// one whose session has reached its final state has ended, and a send naming it
    /// is reported when it is made.
    public func isInvocationRunning(_ invokeID: String) -> Bool {
        if invokeID.utf8.elementsEqual("first_run".utf8) {
            return sceInvokeChildFirstRun.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("lossy_run".utf8) {
            return sceInvokeChildLossyRun.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("missing_run".utf8) {
            return sceInvokeChildMissingRun.map { !$0.isInFinalState } ?? false
        }
        if invokeID.utf8.elementsEqual("second_run".utf8) {
            return sceInvokeChildSecondRun.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Whether a session id names a child of this machine that is running now
    /// (W3C SCXML C.1): the test `deliverToChildSession` makes.
    public func isChildSessionRunning(_ childSessionID: String) -> Bool {
        if childSessionID.isEmpty {
            return false
        }
        if let session = activeInvokes["first_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildFirstRun.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["lossy_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildLossyRun.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["missing_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildMissingRun.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["second_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildSecondRun.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["first_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildFirstRun {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["lossy_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildLossyRun {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["missing_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildMissingRun {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["second_run"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildSecondRun {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        return false
    }


