    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticInvokeHybridState, engine: Engine<StaticInvokeHybridPolicy>, configurationBeforeExit: [StaticInvokeHybridState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .first:
            cancelInvokesForState(&pendingInvokes, .first)
            sceInvokeChildFirstRun?.stop()
            sceInvokeChildFirstRun = nil
            activeInvokes["first_run"] = nil
            sceInvokeDoneFirstRun = false
        case .lossy:
            cancelInvokesForState(&pendingInvokes, .lossy)
            sceInvokeChildLossyRun?.stop()
            sceInvokeChildLossyRun = nil
            activeInvokes["lossy_run"] = nil
            sceInvokeDoneLossyRun = false
        case .missing:
            cancelInvokesForState(&pendingInvokes, .missing)
            sceInvokeChildMissingRun?.stop()
            sceInvokeChildMissingRun = nil
            activeInvokes["missing_run"] = nil
            sceInvokeDoneMissingRun = false
        case .second:
            cancelInvokesForState(&pendingInvokes, .second)
            sceInvokeChildSecondRun?.stop()
            sceInvokeChildSecondRun = nil
            activeInvokes["second_run"] = nil
            sceInvokeDoneSecondRun = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: StaticInvokeHybridState,
        event: StaticInvokeHybridEvent,
        engine: Engine<StaticInvokeHybridPolicy>
    ) -> EnabledTransition<StaticInvokeHybridState>? {
        switch state {
        case .first:
            if event == .doneInvokeFirstRun {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.second)],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        case .lossy:
            if event == .doneInvokeLossyRun {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.missing)],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        case .missing:
            if event == .doneInvokeMissingRun {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.over)],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        case .run:
            if event == .errorExecution {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        case .second:
            if event == .doneInvokeSecondRun {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.lossy)],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

